// We store both leafs and branches in the same tree, so for non-recursive walks,
// we need to walk until the end, but can skip
// any not belonging to child branches.
// Note that the walk is in lexicographic order, so descendants of
// one branch may come after another branch (e.g. "/s1/p1" vs "/s1-foo/..."),
// so we need to check all of the branch prefixes seen so far.
shouldSkip := false
for i := 0; i < len(otherBranches); i++ {
	b := otherBranches[i]
	if strings.HasPrefix(key, b) {
		shouldSkip = true
		break
	}
	if key > b {
		// The walk is sorted, so this branch can never match again.
		otherBranches = append(otherBranches[:i], otherBranches[i+1:]...)
		i--
	}
}
if shouldSkip {
	return false, nil
}

