// any not belonging to child branches.
if otherBranch != "" {
	branchLen := len(otherBranch)
	keyLen := len(key)
	if keyLen >= branchLen {
		matchedPrefix := true
		for i := 0; i < branchLen; i++ {
			if key[i] != otherBranch[i] {
				matchedPrefix = false
				break
			}
		}
		if matchedPrefix {
			return false, nil
		}
	}
}

